function studio():void{
    $u=need_user('artist');$a=one('SELECT * FROM artist_profiles WHERE user_id=?',[$u['id']]);$list=all('SELECT * FROM listings WHERE seller_id=? ORDER BY id DESC',[$u['id']]);page_heading('THE ARTIST WORKSPACE','Your studio. Your next possibility.','A place for your work, your ideas, and the people who connect with them.');
    echo '<div class="stats-grid"><div><small>Your listings</small><strong>'.count($list).'</strong></div><div><small>Portfolio works</small><strong>'.query('SELECT COUNT(*) FROM artworks WHERE artist_id=?',[$u['id']])->fetchColumn().'</strong></div><div><small>Artist badge</small>'.badge($a['badge']).'</div><div><small>Your public space</small><a class="text-link" href="'.url('artist',['id'=>$u['id']]).'">View my Museo '.icon('arrow').'</a></div></div>';
    $edit=!empty($_GET['edit'])?listing((int)$_GET['edit']):null;if($edit&&$edit['seller_id']!==$u['id'])throw new DomainException('This is not your listing.');
    if($edit){echo '<section class="panel"><h2>Edit listing</h2>';form('listing_edit',['id'=>$edit['id']]);echo '<label>Title<input name="title" value="'.e($edit['title']).'" maxlength="120" required></label><label>Description<textarea name="description" required>'.e($edit['description']).'</textarea></label><div class="form-row"><label>Price (PHP)<input name="price" type="number" min="0.01" step="0.01" value="'.($edit['unit_price_centavos']/100).'" required></label><label>Stock<input name="stock" type="number" min="0" value="'.$edit['stock_qty'].'" required></label></div><button class="btn">Save listing</button></form></section>';}
    ?><details class="panel publish-panel" id="publish" <?=isset($_GET['new'])?'open':''?>><summary><span><?=icon('plus')?> Put something new into the world</span><span class="muted">Create a listing</span></summary><form method="post" action="/" enctype="multipart/form-data"><?=token_field()?><input type="hidden" name="action" value="listing_create"><input type="hidden" name="return" value="/?p=studio&new=1"><div class="form-row"><label>Section<select name="section" id="new-section"><?php foreach(SECTIONS as $s=>$v):?><option value="<?=$s?>"><?=$v[0]?> — <?=$v[1]?></option><?php endforeach;?></select></label><label>Category<input name="category" required maxlength="80" placeholder="Landscape, handmade craft, brushes…"></label></div><label>Title<input name="title" maxlength="120" required placeholder="Give your work a name"></label><label>Description<textarea name="description" maxlength="4000" required placeholder="The story, materials, details, and what makes it yours."></textarea></label><div class="form-row"><label>Price / daily rate / starting price (PHP)<input name="price" type="number" min="0.01" max="99999999" step="0.01" required></label><label>Available quantity<input name="stock" type="number" min="1" max="9999" value="1" required></label></div><div class="form-row"><label>Image (JPEG, PNG, WebP · max 5 MB)<input name="image" type="file" accept="image/jpeg,image/png,image/webp" required data-preview="listing-preview"></label><label>Image description<input name="image_alt" maxlength="300" placeholder="A short description for accessibility"></label></div><img id="listing-preview" class="upload-preview" alt="Selected image preview" hidden><div class="form-row"><label>Medium<input name="medium" value="Oil on canvas" maxlength="100"></label><label class="checkbox-label"><input type="checkbox" name="original" value="1"> This is a one-of-a-kind original artwork</label></div><p class="form-hint">Museo and Subasta always create a portfolio artwork with stock 1. Check Original for unique art in Likha Lokal.</p><fieldset data-section-fields="subasta"><legend>Auction details</legend><div class="form-row"><label>Start (Philippine time)<input name="start_time" type="datetime-local" value="<?=date('Y-m-d\TH:i')?>"></label><label>End (Philippine time)<input name="end_time" type="datetime-local" value="<?=date('Y-m-d\TH:i',strtotime('+2 days'))?>"></label></div><label>Minimum bid increment (PHP)<input name="increment" type="number" min="1" step="0.01" value="50"></label></fieldset><fieldset data-section-fields="gawang_hiling"><legend>Commission details</legend><div class="form-row"><label>Slot capacity<input name="capacity" type="number" min="1" max="20" value="3"></label><label>Estimated days<input name="days" type="number" min="1" max="365" value="14"></label><label>Included revisions<input name="revisions" type="number" min="0" max="10" value="2"></label></div><label>Terms<textarea name="terms">Two revisions included. Personal use. Final price and date agreed before work begins.</textarea></label></fieldset><button class="btn">Publish listing <?=icon('arrow')?></button></form></details>
    <div class="section-heading"><h2>On your studio wall</h2><a class="text-link" href="<?=url('work')?>">Manage requests <?=icon('arrow')?></a></div><div class="panel table-wrap"><table><thead><tr><th>Work / item</th><th>Section</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($list as $l):?><tr><td><a href="<?=url('detail',['id'=>$l['id']])?>"><strong><?=e($l['title'])?></strong></a></td><td><?=SECTIONS[$l['section']][0]?></td><td><?=money((int)$l['unit_price_centavos'])?></td><td><?=$l['stock_qty']?></td><td><?=status($l['status'])?></td><td><div class="button-row"><?php if($l['section']!=='subasta'&&$l['status']==='published'):?><a class="btn btn-small btn-outline" href="<?=url('studio',['edit'=>$l['id']])?>">Edit</a><?php endif;if($l['section']!=='subasta'&&in_array($l['status'],['published','paused']))action_button('listing_pause',['id'=>$l['id']],$l['status']==='paused'?'Resume':'Pause','btn btn-small btn-outline');?></div></td></tr><?php endforeach;?></tbody></table></div><section class="panel badge-panel"><div><span class="eyebrow">YOUR CREATIVE JOURNEY</span><h2>A little recognition for your craft.</h2><?=badge($a['badge'])?><p>Sibol welcomes new creators. Dalubhasa recognizes experienced artists after an Admin portfolio review.</p></div><div><?php if($a['badge']==='sibol'){$pending=one("SELECT id FROM badge_reviews WHERE artist_id=? AND status='pending'",[$u['id']]);if($pending)echo '<p class="notice">Your portfolio review is pending.</p>';else{form('badge_apply');echo '<label>Your experience and portfolio statement<textarea name="statement" required maxlength="2000" placeholder="Tell us about your art practice. You need at least 3 visible portfolio works."></textarea></label><button class="btn btn-outline">Request Dalubhasa review</button></form>';}}else echo '<p>Your profile carries the Dalubhasa badge. Keep sharing your craft.</p>';foreach(all('SELECT * FROM badge_reviews WHERE artist_id=? ORDER BY id DESC LIMIT 3',[$u['id']]) as $r)echo '<p class="form-hint">'.e(ucfirst($r['status'])).': '.e($r['decision_reason']??'Awaiting review').'</p>';?></div></section><?php
}
function admin():void{
    need_user('admin');page_heading('ADMIN WORKSPACE','Keep the creative space in good hands.','Review people, content, and the small details that keep SIKHAYA working.');echo '<div class="stats-grid">';foreach(['Accounts'=>'SELECT COUNT(*) FROM users','Published listings'=>"SELECT COUNT(*) FROM listings WHERE status='published'",'Open reports'=>"SELECT COUNT(*) FROM reports WHERE status='open'",'Demo gross sales'=>"SELECT COALESCE(SUM(total_centavos),0) FROM orders WHERE payment_status='demo_paid'"] as $label=>$sql){$n=query($sql)->fetchColumn();echo '<div><small>'.$label.'</small><strong>'.($label==='Demo gross sales'?money((int)$n):$n).'</strong></div>';}echo '</div><div class="admin-nav"><a href="#reviews">Badge reviews</a><a href="#reports">Reports</a><a href="#fees">Rental fees</a><a href="#moderation">Content & accounts</a><a href="#transactions">Transactions</a></div>';
    echo '<section class="panel" id="reviews"><h2>Dalubhasa portfolio reviews</h2>';foreach(all("SELECT r.*,u.display_name FROM badge_reviews r JOIN users u ON u.id=r.artist_id WHERE r.status='pending'") as $r){echo '<div class="admin-review"><a class="text-link" href="'.url('artist',['id'=>$r['artist_id']]).'">'.e($r['display_name']).' · View portfolio</a><p>'.e($r['statement']).'</p>';form('admin_badge',['id'=>$r['id']]);echo '<label>Decision reason<input name="reason" required maxlength="1000" placeholder="Record what you reviewed"></label><select name="decision" aria-label="Badge decision"><option value="approve">Approve Dalubhasa</option><option value="reject">Reject application</option></select><button class="btn btn-small">Save review</button></form></div>';}echo '</section><section class="panel" id="reports"><h2>Community reports</h2>';foreach(all('SELECT r.*,u.display_name FROM reports r JOIN users u ON u.id=r.reporter_id ORDER BY r.id DESC LIMIT 30') as $r){echo '<div class="admin-review"><div class="simple-row"><strong>Report #'.$r['id'].' · '.e($r['display_name']).'</strong>'.status($r['status']).'</div><p>'.e($r['reason']).'</p>';if($r['post_id'])echo '<a class="text-link" href="'.url('feed',['post'=>$r['post_id']]).'">Open reported post</a>';if($r['listing_id'])echo '<a class="text-link" href="'.url('detail',['id'=>$r['listing_id']]).'">Open reported listing</a>';if($r['status']==='open'){form('admin_report',['id'=>$r['id']]);echo '<label>Resolution note<input name="reason" required maxlength="1000" placeholder="Record review or action taken"></label><button class="btn btn-small btn-outline">Resolve report</button></form>';}else echo '<p class="form-hint">'.e($r['resolution_note']).'</p>';echo '</div>';}echo '</section><section class="panel" id="fees"><h2>Rental commission by duration</h2><p>Future requests use these rates. Existing quotes keep their saved rates.</p>';form('admin_rates');echo '<div class="form-row">';foreach(all('SELECT * FROM rental_rate_tiers ORDER BY min_days') as $r)echo '<label>'.$r['min_days'].'–'.$r['max_days'].' days (%)<input type="number" name="rate'.$r['id'].'" min="0" max="100" step="0.01" value="'.($r['commission_bps']/100).'" required></label>';echo '</div><button class="btn btn-small">Update future rates</button></form></section>';
    echo '<section class="panel" id="moderation"><h2>Content & account moderation</h2><p>A reason is required for every action. Transaction records are preserved.</p>';
    $type=(string)($_GET['type']??'listing');$maps=['listing'=>['listings','title'],'artwork'=>['artworks','title'],'post'=>['posts','body'],'comment'=>['comments','body'],'user'=>['users','display_name']];if(!isset($maps[$type]))$type='listing';echo '<div class="catalog-tabs">';foreach($maps as $k=>$v)echo '<a class="'.($k===$type?'selected':'').'" href="'.url('admin',['type'=>$k]).'#moderation">'.ucfirst($k).'s</a>';echo '</div><div class="table-wrap"><table><thead><tr><th>Record</th><th>Status</th><th>Review action</th></tr></thead><tbody>';[$table,$name]=$maps[$type];foreach(all("SELECT * FROM $table ".($type==='user'?"WHERE role<>'admin' ":'').'ORDER BY id DESC LIMIT 30') as $row){$hidden=in_array($row['status'],['hidden','suspended']);echo '<tr><td>#'.$row['id'].' '.e(mb_strimwidth($row[$name],0,90,'…')).'</td><td>'.status($row['status']).'</td><td>';form('admin_moderate',['id'=>$row['id'],'type'=>$type,'step'=>$hidden?'restore':'hide'],'admin-action');echo '<input name="reason" aria-label="Moderation reason for '.$type.' '.$row['id'].'" required maxlength="1000" placeholder="Reason"><button class="btn btn-small btn-outline">'.($hidden?'Restore':($type==='user'?'Suspend':'Hide')).'</button></form></td></tr>';}echo '</tbody></table></div></section>';
    echo '<section class="panel" id="transactions"><h2>Saved demo transactions</h2><div class="table-wrap"><table><thead><tr><th>Order</th><th>Buyer</th><th>Type</th><th>Total</th><th>Payment state</th></tr></thead><tbody>';foreach(all('SELECT o.*,u.display_name FROM orders o JOIN users u ON u.id=o.buyer_id ORDER BY o.id DESC LIMIT 40') as $o)echo '<tr><td>'.e($o['order_number']).'</td><td>'.e($o['display_name']).'</td><td>'.e($o['source']).'</td><td>'.money((int)$o['total_centavos']).'</td><td>'.status($o['payment_status']).'</td></tr>';echo '</tbody></table></div><h3>Rental activity</h3>';foreach(all('SELECT r.*,l.title FROM rental_bookings r JOIN listings l ON l.id=r.listing_id ORDER BY r.id DESC LIMIT 20') as $r)echo '<div class="simple-row"><span>#'.$r['id'].' '.e($r['title']).' · '.e($r['start_date']).' → '.e($r['end_date']).'</span>'.status($r['status']).'</div>';echo '<h3>Custom-art activity</h3>';foreach(all('SELECT r.*,l.title FROM commission_requests r JOIN listings l ON l.id=r.offer_listing_id ORDER BY r.id DESC LIMIT 20') as $r)echo '<div class="simple-row"><span>#'.$r['id'].' '.e($r['title']).' · Due '.e($r['quoted_due_date']??'not quoted').'</span>'.status($r['status']).'</div>';echo '</section>';
}
function studio_full():void {
    studio();$u=need_user('artist');
    $offers=all('SELECT o.*,l.title FROM commission_offers o JOIN listings l ON l.id=o.listing_id WHERE l.seller_id=?',[$u['id']]);
    if(!$offers)return;echo '<section class="panel"><h2>Commission slots & terms</h2><p>New agreements use these settings. Accepted quotes keep their agreed terms.</p>';
    foreach($offers as $o){echo '<details><summary>'.e($o['title']).' · '.slots((int)$o['listing_id']).' slots open</summary>';form('offer_update',['id'=>$o['listing_id']]);echo '<div class="form-row"><label>Capacity<input type="number" min="1" max="20" name="capacity" value="'.$o['slot_capacity'].'" required></label><label>Estimated days<input name="days" type="number" min="1" max="365" value="'.$o['estimated_days'].'" required></label><label>Revisions<input name="revisions" type="number" min="0" max="10" value="'.$o['revision_limit'].'" required></label></div><label>Terms<textarea name="terms" required maxlength="2000">'.e($o['terms']).'</textarea></label><button class="btn btn-small btn-outline">Update future offers</button></form></details>';}
    echo '</section>';
}
function admin_full():void {
    admin();echo '<section class="panel"><h2>Badge revocations</h2><p>Revocation returns an artist to Sibol and records the reason.</p>';
    foreach(all("SELECT u.id,u.display_name FROM users u JOIN artist_profiles a ON a.user_id=u.id WHERE a.badge='dalubhasa'") as $a){form('admin_revoke',['id'=>$a['id']],'admin-action');echo '<strong>'.e($a['display_name']).'</strong><input name="reason" required maxlength="1000" aria-label="Revocation reason for '.e($a['display_name']).'" placeholder="Reason"><button class="btn btn-small btn-outline">Revoke Dalubhasa</button></form><hr>';}
    echo '</section><section class="panel"><h2>Cancel unfulfilled order items</h2><p>Admin only. This records a simulated refund when paid, releases eligible stock/dates/slots, and keeps the original receipt. Completed or collected items cannot be cancelled.</p><div class="table-wrap"><table><thead><tr><th>Order item</th><th>State</th><th>Cancellation reason</th></tr></thead><tbody>';
    foreach(all("SELECT i.*,o.order_number FROM order_items i JOIN orders o ON o.id=i.order_id WHERE i.status NOT IN ('completed','cancelled') ORDER BY i.id DESC LIMIT 30") as $i){echo '<tr><td>'.e($i['order_number']).'<br>'.e($i['item_title']).'</td><td>'.status($i['status']).'</td><td>';form('admin_cancel',['id'=>$i['id']],'admin-action');echo '<input name="reason" required maxlength="1000" aria-label="Cancellation reason for order item '.$i['id'].'" placeholder="Record a clear reason"><button class="btn btn-small btn-outline">Cancel item</button></form></td></tr>';}
    echo '</tbody></table></div></section>';
}
function activity():void{
    $u=need_user();page_heading('A LITTLE UPDATE','From around your creative world.','Bids, projects, orders, and what’s happening next.');action_button('read_notices',[],'Mark all as read','btn btn-outline');echo '<div class="panel">';$rows=all('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100',[$u['id']]);if(!$rows)echo '<p>All quiet for now.</p>';foreach($rows as $r)echo '<a class="notification '.($r['read_at']?'':'unread').'" href="'.e(str_starts_with($r['target_path'],'/?p=')?$r['target_path']:'/?p=home').'">'.icon('bell').'<span>'.e($r['message']).'<small>'.date('M j, g:i A',strtotime($r['created_at'])).'</small></span>'.icon('arrow').'</a>';echo '</div>';
}
function about():void{
    page_heading('SIKHAY + LAYA','A home for Filipino creativity.','Alisin ang tanikala, lumikha nang malaya.');?><div class="about-layout"><div class="about-logo"><img src="/assets/images/sikhaya-logo.png" alt="SIKHAYA original fire, air, wood, and paintbrush logo"></div><div class="prose"><h2>Hard work meets freedom.</h2><p>Sikhaya connects Filipino artists with art enthusiasts, collectors, and buyers. Artists can show and sell original artworks, accept commissions, join online art auctions, and access art materials and multimedia equipment.</p><p>The name brings together <strong>sikhay</strong> — hard work, dedication, and passion — and <strong>laya</strong>, from <em>malaya</em> — the freedom to express, create, and be yourself.</p><h2>A name you can see.</h2><p>Fire is Sikhay. Air is Laya. Together, they form the letter S and flow from the tip of a paintbrush. Brown, wood-textured letters ground the name in the hands and materials of making.</p></div></div><div class="two-columns"><section class="panel"><span class="eyebrow">OUR VISION</span><h2>Local art, given room to grow.</h2><p>To empower and unite local Filipino artists by providing a space to showcase, sell, and discover local artworks, and to preserve artistic culture.</p></section><section class="panel"><span class="eyebrow">OUR MISSION</span><h2>Creative passion. Real opportunity.</h2><p>To build a home for local artists and creators where artwork gets the spotlight it deserves, and to fill the gap between creative passion and real opportunity by giving people a smooth way to share artworks.</p></section></div><div class="section-heading"><h2>What we’re here to do.</h2></div><div class="objectives"><?php foreach(['Empower Artists'=>'Give Filipino creators a place to show and sell their work.','Connect Buyers and Creators'=>'Bring art enthusiasts and local talent together.','Promote Culture'=>'Give regional art and stories a place to be seen.','Create Opportunity'=>'Help creative passion find a path to meaningful work.'] as $h=>$p):?><div><?=icon('spark')?><h3><?=$h?></h3><p><?=$p?></p></div><?php endforeach;?></div><section class="panel prose"><span class="eyebrow">THE ENTREPRENEURIAL MIND</span><h2>A school project, made together.</h2><p>Dela Cruz, Jay Ar · Dela Cruz, Jhay Ruz · Martin, Thomas · Paraiso Jr, Joven · Sacobo, Queenzel</p><p>Submitted to Mr. Naz Eliseo Carcosia.</p><p>This localhost prototype uses fictional accounts and listings. The artwork and equipment samples were generated for demonstration; other licensed stand-in photographs are listed in the project’s asset credits. Checkout never charges real money.</p><a class="btn btn-outline" href="<?=url('help')?>">How SIKHAYA works <?=icon('arrow')?></a></section><?php
}
function help():void{
    page_heading('A SMALL GUIDE','A little clarity goes a long way.','How to explore, create, and try the school prototype.');echo '<div class="help-grid">';foreach(SECTIONS as $k=>$v){echo '<section class="panel">'.icon($v[2]).'<h2>'.$v[0].'</h2><p>'.match($k){'subasta'=>'Place bids before the server deadline. The highest accepted bid wins. Winner fake checkout is open for 24 hours. No self-bids or bid withdrawal.','arkilikha'=>'Choose pickup and return dates. One listing is one unit; dates cannot overlap. Request approval, then complete fake checkout within 24 hours. Return date is excluded.','gawang_hiling'=>'Send your idea. The artist quotes a price and date; accept within 72 hours, then fake checkout within 24 hours. Progress and delivery stay in your private project thread.','kagamit'=>'Find creative tools and materials. Add available quantities to your cart and use the simulated checkout.','museo'=>'Explore artist portfolios and buy available work. Sibol welcomes new artists. Dalubhasa follows an Admin review of experience and at least three portfolio works.',default=>'Discover original artworks, local materials, sculpture, and handmade crafts. An original artwork can only be sold once.'}.'</p><a class="text-link" href="'.url($k==='museo'?'artists':'catalog',$k==='museo'?[]:['section'=>$k]).'">Explore '.$v[0].' '.icon('arrow').'</a></section>';}echo '</div><section class="panel prose"><h2>Rental fee tiers</h2>';foreach(all('SELECT * FROM rental_rate_tiers WHERE is_active=1 ORDER BY min_days') as $r)echo '<p>'.$r['min_days'].'–'.$r['max_days'].' days: '.($r['commission_bps']/100).'% platform commission.</p>';echo '<p>The renter pays daily price × days. The provider’s demo proceeds are reduced by the platform fee. Rates are saved with each quote.</p><h2>Community, with care.</h2><p>Share artwork you have permission to use. Give credit and respect other creators. React, comment, reply, repost to SIKHAYA, copy a post link, or save something for later. Report content with a reason so an Admin can review it.</p><h2>Try every side of the prototype.</h2><p>Use the Buyer, Artist, or Admin shortcuts on the sign-in page. All demo account passwords are Sikhaya2026!. You can also create your own local account. Data stays on this laptop and is saved after restarting the server.</p><a class="btn" href="'.url('login').'">Open demo accounts '.icon('arrow').'</a></section>';
}
